formula:
lo:=LLV(LOW,9); hi:=HHV(HIGH,9);
raw:=IF(hi=lo,50,(CLOSE-lo)/MAX(hi-lo,0.000001)*100);
rsv:=EMA(raw,3); k:EMA(rsv,3),COLORWHITE,LINETHICK2;
d:MA(k,3),COLORYELLOW;
goldenCross:=CROSS(k,d); deadCross:=CROSS(d,k);
lowCross:=goldenCross AND k<=50; highCross:=deadCross AND k>=80;
buy:=goldenCross AND d<8; sell:=deadCross AND d>85;
bottomFractal:=REF(LOW,2)<REF(LOW,3) AND REF(LOW,2)<REF(LOW,4) AND REF(LOW,2)<=REF(LOW,1) AND REF(LOW,2)<=LOW;
topFractal:=REF(HIGH,2)>REF(HIGH,3) AND REF(HIGH,2)>REF(HIGH,4) AND REF(HIGH,2)>=REF(HIGH,1) AND REF(HIGH,2)>=HIGH;
bottomDistance:=BARSLAST(REF(bottomFractal,1))+1; topDistance:=BARSLAST(REF(topFractal,1))+1;
kLow:=LLV(k,5); kHigh:=HHV(k,5);
bottomDivergence:=bottomFractal AND bottomDistance>=5 AND bottomDistance<=60 AND REF(LOW,2)<REF(LOW,bottomDistance+2) AND kLow>REF(kLow,bottomDistance);
topDivergence:=topFractal AND topDistance>=5 AND topDistance<=60 AND REF(HIGH,2)>REF(HIGH,topDistance+2) AND kHigh<REF(kHigh,topDistance);
bottomWatch:=BARSLAST(bottomDivergence)<25; topWatch:=BARSLAST(topDivergence)<25;
angel:=EMA(CLOSE,2); devil:=EMA(CLOSE+20*SLOPE(CLOSE,21),42);
turnBull:=CROSS(angel,devil); turnBear:=CROSS(devil,angel);
trial:=bottomWatch AND turnBull AND k>d;
reduce:=topWatch AND ((deadCross AND k>=50) OR turnBear);
STICKLINE(k>d,k,d,2,0),COLORRED;
STICKLINE(k<=d,k,d,2,0),COLORGREEN;
HLINE(90,'逃顶线 90'),COLORGREEN;
HLINE(50,'中轴线 50'),COLORRED;
HLINE(10,'抄底线 10'),COLORYELLOW;
DRAWICON(lowCross,12,1),COLORRED; DRAWICON(highCross,88,2),COLORGREEN;
DRAWTEXT(bottomDivergence,18,'底背离'),COLORRED;
DRAWTEXT(topDivergence,82,'顶背离'),COLORGREEN;
DRAWTEXT(buy,30,'超卖金叉'),COLORRED; DRAWTEXT(sell,70,'超买死叉'),COLORGREEN;
DRAWTEXT(trial,40,'试仓'),COLORYELLOW; DRAWTEXT(reduce,60,'减仓'),COLORGREEN;
TOOLTIP(k,'K'),COLORWHITE; TOOLTIP(d,'D'),COLORYELLOW;
